import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { api, getError } from '../api';

const money = (value) => `₹${Number(value || 0).toLocaleString('en-IN')}`;
const date = (value) => value ? new Date(value).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';
const statusTone = { available: 'bg-emerald-50 text-emerald-800', accepted: 'bg-emerald-50 text-emerald-800', approved: 'bg-emerald-50 text-emerald-800', pending: 'bg-amber-50 text-amber-800', shortlisted: 'bg-sky-50 text-sky-800', booked: 'bg-violet-50 text-violet-800', declined: 'bg-rose-50 text-rose-800', rejected: 'bg-rose-50 text-rose-800', removed: 'bg-slate-100 text-slate-600', withdrawn: 'bg-slate-100 text-slate-600', suspended: 'bg-rose-50 text-rose-800' };
const Button = ({ children, tone = 'primary', className = '', ...props }) => <button {...props} className={`inline-flex min-h-10 items-center justify-center rounded-lg px-4 py-2 text-sm font-semibold transition disabled:cursor-not-allowed disabled:opacity-50 ${tone === 'danger' ? 'bg-rose-700 text-white hover:bg-rose-800' : tone === 'quiet' ? 'border border-slate-300 bg-white text-slate-700 hover:bg-slate-50' : tone === 'success' ? 'bg-emerald-700 text-white hover:bg-emerald-800' : 'bg-indigo-700 text-white hover:bg-indigo-800'} ${className}`}>{children}</button>;
const Notice = ({ children, error }) => children ? <div role="status" className={`rounded-lg px-4 py-3 text-sm ${error ? 'bg-rose-50 text-rose-800' : 'bg-emerald-50 text-emerald-800'}`}>{children}</div> : null;
const Panel = ({ title, subtitle, action, children, className = '' }) => <section className={`rounded-xl border border-slate-200 bg-white shadow-sm ${className}`}><div className="flex flex-wrap items-start justify-between gap-3 border-b border-slate-100 px-5 py-4 sm:px-6"><div><h2 className="font-bold text-slate-900">{title}</h2>{subtitle&&<p className="mt-1 text-sm text-slate-500">{subtitle}</p>}</div>{action}</div><div className="p-5 sm:p-6">{children}</div></section>;
const PageHeading = ({ eyebrow, title, copy, action }) => <header className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-indigo-700">{eyebrow}</p><h1 className="mt-1 text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">{title}</h1>{copy&&<p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{copy}</p>}</div>{action}</header>;
const Badge = ({ value }) => <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold capitalize ${statusTone[value] || 'bg-slate-100 text-slate-700'}`}>{value}</span>;
const Stat = ({ label, value, detail, accent = false }) => <div className={`rounded-xl border p-4 sm:p-5 ${accent ? 'border-indigo-100 bg-indigo-50/70' : 'border-slate-200 bg-white'}`}><p className="text-sm font-medium text-slate-500">{label}</p><p className="mt-2 text-2xl font-bold tracking-tight text-slate-950">{value ?? '—'}</p>{detail&&<p className="mt-1 text-xs text-slate-500">{detail}</p>}</div>;
const SearchField = ({ value, onChange, placeholder = 'Search by name, room or area' }) => <input value={value} onChange={(event)=>onChange(event.target.value)} placeholder={placeholder} className="min-h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm outline-none focus:border-indigo-600" />;
const Select = ({ value, onChange, options, label }) => <label className="flex items-center gap-2 text-sm text-slate-500"><span className="sr-only">{label}</span><select value={value} onChange={(event)=>onChange(event.target.value)} className="min-h-10 w-full rounded-lg border border-slate-300 bg-white px-3 text-sm text-slate-800 outline-none focus:border-indigo-600">{options.map((option)=>Array.isArray(option)?<option key={option[0]} value={option[0]}>{option[1]}</option>:<option key={option}>{option}</option>)}</select></label>;
const Empty = ({ title, copy, action }) => <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50/70 px-5 py-10 text-center"><h3 className="font-semibold text-slate-800">{title}</h3><p className="mx-auto mt-1 max-w-md text-sm leading-6 text-slate-500">{copy}</p>{action&&<div className="mt-4">{action}</div>}</div>;
const ErrorNotice = ({ error }) => error ? <Notice error>{error}</Notice> : null;

function ProfileSettings({ user, onUpdated }) {
  const [profile,setProfile]=useState({name:user.name||'',phone:user.phone||''}),[passwords,setPasswords]=useState({currentPassword:'',newPassword:''}),[error,setError]=useState(''),[message,setMessage]=useState('');
  const saveProfile=async(event)=>{event.preventDefault();setError('');setMessage('');try{const {data}=await api.patch('/auth/profile',profile);onUpdated(data.user);setMessage('Profile details saved.');}catch(e){setError(getError(e));}};
  const changePassword=async(event)=>{event.preventDefault();setError('');setMessage('');try{const {data}=await api.patch('/auth/password',passwords);setPasswords({currentPassword:'',newPassword:''});setMessage(data.message);}catch(e){setError(getError(e));}};
  return <Panel title="Account & security" subtitle="Keep your contact details current and protect your account."><Notice error={error}/><Notice>{message}</Notice><div className="grid gap-6 lg:grid-cols-2"><form onSubmit={saveProfile} className="space-y-3"><h3 className="text-sm font-bold text-slate-800">Profile details</h3><label className="block text-sm font-medium text-slate-700">Full name<input required value={profile.name} onChange={(e)=>setProfile({...profile,name:e.target.value})} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="block text-sm font-medium text-slate-700">Phone number<input type="tel" value={profile.phone} onChange={(e)=>setProfile({...profile,phone:e.target.value})} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><p className="text-sm text-slate-500">Login email: {user.email}</p><Button>Save profile</Button></form><form onSubmit={changePassword} className="space-y-3"><h3 className="text-sm font-bold text-slate-800">Change password</h3><label className="block text-sm font-medium text-slate-700">Current password<input type="password" required value={passwords.currentPassword} onChange={(e)=>setPasswords({...passwords,currentPassword:e.target.value})} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="block text-sm font-medium text-slate-700">New password<input type="password" minLength="8" required value={passwords.newPassword} onChange={(e)=>setPasswords({...passwords,newPassword:e.target.value})} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><p className="text-xs text-slate-500">Use at least 8 characters. Your new password is stored securely.</p><Button tone="quiet">Update password</Button></form></div></Panel>;
}

function DashboardTabs({ value, onChange, items }) {
  return <div className="mb-6 flex gap-1 overflow-x-auto border-b border-slate-200" role="tablist">{items.map(([id,label,count])=><button key={id} role="tab" aria-selected={value===id} onClick={()=>onChange(id)} className={`shrink-0 border-b-2 px-4 py-3 text-sm font-semibold transition ${value===id?'border-indigo-700 text-indigo-800':'border-transparent text-slate-500 hover:text-slate-900'}`}>{label}{count!==undefined&&<span className="ml-2 rounded-full bg-slate-100 px-2 py-0.5 text-xs text-slate-600">{count}</span>}</button>)}</div>;
}

export function StudentDashboard({ user, onUpdated }) {
  const [items,setItems]=useState([]),[filter,setFilter]=useState('all'),[query,setQuery]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState('');
  const refresh=()=>api.get('/applications/mine').then(({data})=>{setItems(data);setError('');}).catch((e)=>setError(getError(e)));
  useEffect(()=>{refresh();},[]);
  const counts=useMemo(()=>Object.fromEntries(['all','pending','shortlisted','accepted','declined','withdrawn'].map((status)=>[status,status==='all'?items.length:items.filter((item)=>item.status===status).length])),[items]);
  const shown=items.filter((item)=>(filter==='all'||item.status===filter)&&`${item.room?.title||''} ${item.room?.area||''} ${item.room?.city||''}`.toLowerCase().includes(query.toLowerCase()));
  const withdraw=async(id)=>{setBusy(id);setError('');try{await api.patch(`/applications/mine/${id}/withdraw`);await refresh();}catch(e){setError(getError(e));}finally{setBusy('');}};
  return <div className="space-y-6"><PageHeading eyebrow="Student account" title="Your applications" copy="Keep track of your room requests and see the latest response from each owner." action={<Link to="/rooms" className="inline-flex min-h-10 items-center justify-center rounded-lg bg-indigo-700 px-4 py-2 text-sm font-semibold text-white hover:bg-indigo-800">Find a room</Link>} /><ErrorNotice error={error}/>
    <div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Stat label="Applications sent" value={items.length} detail="Across all room listings" accent/><Stat label="Awaiting response" value={counts.pending||0} detail="Owners are reviewing"/><Stat label="Shortlisted" value={counts.shortlisted||0} detail="Owners want to connect"/><Stat label="Accepted" value={counts.accepted||0} detail="Your next step is to contact the owner"/></div>
    <Panel title="Application history" subtitle="Updates appear here as room owners review your requests." action={<div className="w-full sm:w-64"><SearchField value={query} onChange={setQuery}/></div>}>
      <DashboardTabs value={filter} onChange={setFilter} items={['all','pending','shortlisted','accepted','declined','withdrawn'].map((s)=>[s,s==='all'?'All':s[0].toUpperCase()+s.slice(1),counts[s]])}/>
      {shown.length?<div className="space-y-3">{shown.map((application)=><article key={application._id} className="rounded-xl border border-slate-200 p-4 sm:p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h3 className="font-bold text-slate-900">{application.room?.title||'Room listing'}</h3><Badge value={application.status}/></div><p className="mt-1 text-sm text-slate-500">{application.room?.area}, {application.room?.city}</p><p className="mt-3 text-sm font-semibold text-slate-800">{money(application.room?.rent)} <span className="font-normal text-slate-500">per month</span></p></div><Link to={`/rooms/${application.room?._id}`} className="text-sm font-semibold text-indigo-700 hover:underline">View listing</Link></div><div className="mt-4 grid gap-2 border-t border-slate-100 pt-4 text-sm text-slate-600 sm:grid-cols-3"><p>Applied <b className="font-medium text-slate-800">{date(application.createdAt)}</b></p><p>Move-in <b className="font-medium text-slate-800">{date(application.moveInDate)}</b></p><p>College <b className="font-medium text-slate-800">{application.college}</b></p></div>{application.message&&<p className="mt-3 rounded-lg bg-slate-50 p-3 text-sm leading-6 text-slate-600">{application.message}</p>}{application.warnings?.map((warning,index)=><p key={index} className="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">Account note: {warning.reason}</p>)}{['pending','shortlisted'].includes(application.status)&&<div className="mt-4 flex justify-end"><Button tone="quiet" disabled={busy===application._id} onClick={()=>withdraw(application._id)}>{busy===application._id?'Updating…':'Withdraw application'}</Button></div>}</article>)}</div>:<Empty title={items.length?'No matching applications':'No applications yet'} copy={items.length?'Try another search or status filter.':'Browse available rooms and send a request to start tracking your search.'} action={!items.length&&<Link to="/rooms" className="font-semibold text-indigo-700">Browse available rooms →</Link>}/>}
    </Panel><ProfileSettings user={user} onUpdated={onUpdated}/>
  </div>;
}

const roomFormFrom = (room) => ({ title:room?.title||'', description:room?.description||'', city:room?.city||'', area:room?.area||'', address:room?.address||'', rent:room?.rent||'', size:room?.size||'', deposit:room?.deposit||0, minimumStayMonths:room?.minimumStayMonths||1, availableFrom:room?.availableFrom?new Date(room.availableFrom).toISOString().slice(0,10):'', roomType:room?.roomType||'PG', furnishing:room?.furnishing||'Furnished', bathroom:room?.bathroom||'Shared', water:room?.utilities?.water||'Included', electricity:room?.utilities?.electricity||'Included', other:room?.utilities?.other||'', features:room?.features?.join(', ')||'', images:room?.images?.join('\n')||'' });
const imageToBase64 = (blob) => new Promise((resolve,reject) => { const reader=new FileReader(); reader.onload=()=>resolve(String(reader.result).split(',')[1]); reader.onerror=()=>reject(new Error('Could not read the selected photo.')); reader.readAsDataURL(blob); });
async function compressRoomPhoto(file) {
  const bitmap=await createImageBitmap(file);
  const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));
  const canvas=document.createElement('canvas'); canvas.width=Math.round(bitmap.width*scale); canvas.height=Math.round(bitmap.height*scale);
  canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height); bitmap.close();
  const blob=await new Promise((resolve)=>canvas.toBlob(resolve,'image/jpeg',0.82));
  if(!blob) throw new Error(`Could not compress ${file.name}.`);
  if(blob.size>1024*1024) throw new Error(`${file.name} is too large. Choose a smaller image.`);
  return {contentType:'image/jpeg',data:await imageToBase64(blob)};
}
function RoomEditor({ room, onSave, onCancel, saving }) {
  const [form,setForm]=useState(()=>roomFormFrom(room));
  const [photos,setPhotos]=useState([]),[photoError,setPhotoError]=useState('');
  const photoPreviews=useMemo(()=>photos.map((file)=>({file,url:URL.createObjectURL(file)})),[photos]);
  useEffect(()=>()=>photoPreviews.forEach(({url})=>URL.revokeObjectURL(url)),[photoPreviews]);
  const set=(key,value)=>setForm((old)=>({...old,[key]:value}));
  const selectPhotos=(files)=>{setPhotoError('');const valid=Array.from(files||[]).filter((file)=>['image/jpeg','image/png','image/webp'].includes(file.type));if(valid.length!==(files?.length||0)){setPhotoError('Choose JPEG, PNG or WebP images.');return;}const remaining=Math.max(0,8-form.images.split('\n').filter((x)=>x.trim()).length-photos.length);setPhotos((old)=>[...old,...valid.slice(0,remaining)]);if(valid.length>remaining)setPhotoError('A room can have up to 8 photos total.');};
  const submit=(event)=>{event.preventDefault();onSave({...form,rent:Number(form.rent),size:Number(form.size),deposit:Number(form.deposit||0),minimumStayMonths:Number(form.minimumStayMonths||1),features:form.features.split(',').map((x)=>x.trim()).filter(Boolean),images:form.images.split('\n').map((x)=>x.trim()).filter(Boolean),newPhotos:photos,utilities:{water:form.water,electricity:form.electricity,other:form.other}});};
  return <form onSubmit={submit} className="grid gap-3 sm:grid-cols-2"><label className="text-sm font-medium text-slate-700 sm:col-span-2">Listing title<input required value={form.title} onChange={(e)=>set('title',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">City<input required value={form.city} onChange={(e)=>set('city',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">Area<input required value={form.area} onChange={(e)=>set('area',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">Monthly rent (₹)<input type="number" min="0" required value={form.rent} onChange={(e)=>set('rent',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">Room size (m²)<input type="number" min="1" required value={form.size} onChange={(e)=>set('size',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">Deposit (₹)<input type="number" min="0" value={form.deposit} onChange={(e)=>set('deposit',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">Minimum stay (months)<input type="number" min="1" value={form.minimumStayMonths} onChange={(e)=>set('minimumStayMonths',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">Room type<select value={form.roomType} onChange={(e)=>set('roomType',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5">{['PG','Single room','Shared room','Studio','Apartment'].map((x)=><option key={x}>{x}</option>)}</select></label><label className="text-sm font-medium">Furnishing<select value={form.furnishing} onChange={(e)=>set('furnishing',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5">{['Furnished','Semi-furnished','Unfurnished'].map((x)=><option key={x}>{x}</option>)}</select></label><label className="text-sm font-medium">Bathroom<select value={form.bathroom} onChange={(e)=>set('bathroom',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5">{['Shared','Private','Attached'].map((x)=><option key={x}>{x}</option>)}</select></label><label className="text-sm font-medium">Available from<input type="date" value={form.availableFrom} onChange={(e)=>set('availableFrom',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium sm:col-span-2">Street address (shown approximately to students)<input value={form.address} onChange={(e)=>set('address',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium sm:col-span-2">Description<textarea required rows="4" value={form.description} onChange={(e)=>set('description',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium sm:col-span-2">Features (comma separated)<input value={form.features} onChange={(e)=>set('features',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">Water billing<input value={form.water} onChange={(e)=>set('water',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium">Electricity billing<input value={form.electricity} onChange={(e)=>set('electricity',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><label className="text-sm font-medium sm:col-span-2">Other charges<input value={form.other} onChange={(e)=>set('other',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5"/></label><section className="space-y-3 rounded-xl border border-slate-200 bg-slate-50 p-4 sm:col-span-2"><div><h3 className="text-sm font-semibold text-slate-800">Room photos</h3><p className="mt-1 text-xs text-slate-500">Upload up to 8 JPEG, PNG or WebP images. Photos are compressed and stored in the database.</p></div><input type="file" accept="image/jpeg,image/png,image/webp" multiple disabled={saving} onChange={(e)=>selectPhotos(e.target.files)} className="block w-full text-sm text-slate-600 file:mr-3 file:rounded-lg file:border-0 file:bg-indigo-100 file:px-3 file:py-2 file:font-semibold file:text-indigo-800"/>{photoError&&<p role="alert" className="text-sm text-rose-700">{photoError}</p>}{photoPreviews.length>0&&<div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{photoPreviews.map(({file,url},index)=><div key={`${file.name}-${index}`} className="relative overflow-hidden rounded-lg border border-slate-200 bg-white"><img src={url} alt={`Selected room ${index+1}`} className="h-28 w-full object-cover"/><button type="button" onClick={()=>setPhotos((old)=>old.filter((_,i)=>i!==index))} aria-label={`Remove ${file.name}`} className="absolute right-2 top-2 rounded-full bg-white/95 px-2 py-1 text-xs font-semibold text-slate-700 shadow">Remove</button><p className="truncate px-2 py-1 text-xs text-slate-500">{file.name}</p></div>)}</div>}<label className="block text-sm font-medium text-slate-700">Or add hosted photo URLs (one per line)<textarea rows="2" value={form.images} onChange={(e)=>set('images',e.target.value)} className="mt-1 block w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5"/></label></section><div className="flex flex-wrap gap-2 sm:col-span-2"><Button disabled={saving}>{saving?'Uploading photos and saving…':room?'Save changes for review':'Submit listing for review'}</Button>{onCancel&&<Button type="button" tone="quiet" onClick={onCancel}>Cancel</Button>}</div></form>;
}

export function OwnerDashboard({ user, onUpdated }) {
  const [rooms,setRooms]=useState([]),[apps,setApps]=useState([]),[error,setError]=useState(''),[message,setMessage]=useState(''),[tab,setTab]=useState('overview'),[editing,setEditing]=useState(''),[query,setQuery]=useState(''),[appFilter,setAppFilter]=useState('all'),[saving,setSaving]=useState(false);
  const refresh=()=>Promise.all([api.get('/owner/rooms'),api.get('/owner/applications')]).then(([r,a])=>{setRooms(r.data);setApps(a.data);setError('');}).catch((e)=>setError(getError(e)));
  useEffect(()=>{if(user.accountStatus==='approved')refresh();},[user.accountStatus]);
  const roomCounts={all:rooms.length,pending:rooms.filter((r)=>r.status==='pending').length,available:rooms.filter((r)=>r.status==='available').length,booked:rooms.filter((r)=>r.status==='booked').length};
  const appCounts={all:apps.length,pending:apps.filter((a)=>a.status==='pending').length,shortlisted:apps.filter((a)=>a.status==='shortlisted').length,accepted:apps.filter((a)=>a.status==='accepted').length};
  const saveRoom=async(payload,roomId)=>{setSaving(true);setError('');setMessage('');try{const {newPhotos=[],...roomPayload}=payload;if(newPhotos.length){setMessage(`Compressing and uploading ${newPhotos.length} room photo${newPhotos.length===1?'':'s'} to the database…`);const images=await Promise.all(newPhotos.map(compressRoomPhoto));const uploaded=await api.post('/uploads/images',{images});roomPayload.images=[...roomPayload.images,...uploaded.data.images];}if(roomId)await api.patch(`/owner/rooms/${roomId}`,roomPayload);else await api.post('/rooms',roomPayload);setMessage(roomId?'Changes submitted. The listing will be reviewed again before publication.':'Listing submitted for admin review.');setEditing('');setTab('listings');await refresh();}catch(e){setError(getError(e));}finally{setSaving(false);}};
  const updateApp=async(id,status)=>{setError('');try{await api.patch(`/owner/applications/${id}/status`,{status});await refresh();}catch(e){setError(getError(e));}};
  const updateRoom=async(id,status)=>{setError('');try{await api.patch(`/owner/rooms/${id}/status`,{status});await refresh();}catch(e){setError(getError(e));}};
  if(user.accountStatus==='pending')return <Panel title="Owner account under review" subtitle="We’ll unlock your listing tools as soon as your account is approved."><p className="text-sm leading-6 text-slate-600">Your account request is with the Rento team. You can sign in any time to check its status.</p></Panel>;
  if(user.accountStatus!=='approved')return <Panel title="Owner account unavailable"><p className="text-sm leading-6 text-slate-600">Your account is currently {user.accountStatus}. Contact the Rento team if you need help.</p></Panel>;
  const filteredRooms=rooms.filter((r)=>`${r.title} ${r.area} ${r.city}`.toLowerCase().includes(query.toLowerCase()));
  const filteredApps=apps.filter((a)=>(appFilter==='all'||a.status===appFilter)&&`${a.fullName} ${a.room?.title||''} ${a.college}`.toLowerCase().includes(query.toLowerCase()));
  const tabs=[['overview','Overview'],['listings','My listings',rooms.length],['applications','Applications',apps.length],['new','Post a room']];
  return <div className="space-y-6"><PageHeading eyebrow="Owner workspace" title={`Welcome, ${user.name?.split(' ')[0]||'owner'}`} copy="Manage your room advertisements, respond to student requests, and keep availability up to date." action={<Button onClick={()=>{setEditing('new');setTab('new');}}>+ Post a room</Button>}/><ErrorNotice error={error}/><Notice>{message}</Notice>
    <DashboardTabs value={tab} onChange={(next)=>{setTab(next);setEditing(next==='new'?'new':'');setQuery('');}} items={tabs}/>
    {tab==='overview'&&<><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Stat label="Total listings" value={roomCounts.all} detail={`${roomCounts.available} currently available`} accent/><Stat label="Awaiting review" value={roomCounts.pending} detail="Pending admin approval"/><Stat label="Student requests" value={appCounts.all} detail={`${appCounts.pending} need your response`}/><Stat label="Accepted students" value={appCounts.accepted} detail="Confirmed applications"/></div><div className="grid gap-6 xl:grid-cols-2"><Panel title="Recent student requests" subtitle="Respond promptly to help students plan." action={<button onClick={()=>setTab('applications')} className="text-sm font-semibold text-indigo-700">View all</button>}>{apps.slice(0,4).length?<div className="divide-y">{apps.slice(0,4).map((a)=><div key={a._id} className="flex flex-col justify-between gap-2 py-3 first:pt-0 sm:flex-row sm:items-center"><div><p className="font-semibold">{a.fullName}</p><p className="text-sm text-slate-500">{a.room?.title} · {a.college}</p></div><Badge value={a.status}/></div>)}</div>:<Empty title="No requests yet" copy="Student applications will appear here."/>}</Panel><Panel title="Listing status" subtitle="Keep every advertisement accurate and current." action={<button onClick={()=>setTab('listings')} className="text-sm font-semibold text-indigo-700">Manage listings</button>}>{rooms.length?<div className="divide-y">{rooms.slice(0,4).map((r)=><div key={r._id} className="flex flex-col justify-between gap-2 py-3 first:pt-0 sm:flex-row sm:items-center"><div><p className="font-semibold">{r.title}</p><p className="text-sm text-slate-500">{r.area}, {r.city} · {money(r.rent)}/mo</p></div><Badge value={r.status}/></div>)}</div>:<Empty title="Add your first room" copy="Create a complete advertisement to reach students searching nearby." action={<Button onClick={()=>setTab('new')}>Create listing</Button>}/>}</Panel></div></>}
    {tab==='new'&&(editing&&editing!=='new'?<Panel title="Edit listing" subtitle="Edited listings go back to admin review before they are visible."><RoomEditor room={rooms.find((r)=>r._id===editing)} saving={saving} onCancel={()=>setEditing('')} onSave={(payload)=>saveRoom(payload,editing)}/></Panel>:<Panel title="Create a room advertisement" subtitle="Add accurate pricing, photos, amenities and billing details. Your listing is reviewed before it goes live."><RoomEditor saving={saving} onSave={(payload)=>saveRoom(payload)}/></Panel>)}
    {tab==='listings'&&<Panel title="Your room advertisements" subtitle="Edit details, update availability, and see moderation feedback." action={<div className="w-full sm:w-64"><SearchField value={query} onChange={setQuery} placeholder="Search your listings"/></div>}>{filteredRooms.length?<div className="grid gap-4 xl:grid-cols-2">{filteredRooms.map((r)=><article key={r._id} className="overflow-hidden rounded-xl border border-slate-200"><div className="flex gap-4 p-4"><img src={r.images?.[0]||'https://images.unsplash.com/photo-1554995207-c18c203602cb?q=80&w=500'} alt="" className="h-24 w-28 shrink-0 rounded-lg object-cover sm:h-28 sm:w-36"/><div className="min-w-0 flex-1"><div className="flex flex-wrap items-start justify-between gap-2"><h3 className="font-bold">{r.title}</h3><Badge value={r.status}/></div><p className="mt-1 text-sm text-slate-500">{r.area}, {r.city}</p><p className="mt-2 font-semibold">{money(r.rent)}<span className="font-normal text-slate-500"> / month</span></p><p className="text-xs text-slate-500">{r.size} m² · {r.roomType}</p></div></div>{r.moderationNote&&<p className="mx-4 mb-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">Admin note: {r.moderationNote}</p>}<div className="flex flex-wrap gap-2 border-t border-slate-100 bg-slate-50 px-4 py-3"><Button tone="quiet" onClick={()=>{setEditing(r._id);setTab('new');}}>Edit details</Button>{r.status==='available'&&<Button tone="quiet" onClick={()=>updateRoom(r._id,'booked')}>Mark booked</Button>}{r.status==='booked'&&<Button tone="success" onClick={()=>updateRoom(r._id,'available')}>Mark available</Button>}{r.status==='available'&&<Link className="inline-flex min-h-10 items-center px-2 text-sm font-semibold text-indigo-700" to={`/rooms/${r._id}`}>View public page ↗</Link>}</div></article>)}</div>:<Empty title="No matching listings" copy="Try another search term or post a new room." action={<Button onClick={()=>{setEditing('new');setTab('new');}}>Post a room</Button>}/>}</Panel>}
    {tab==='applications'&&<Panel title="Student applications" subtitle="Review each request and keep students informed." action={<div className="flex w-full flex-col gap-2 sm:w-auto sm:flex-row"><div className="sm:w-56"><SearchField value={query} onChange={setQuery}/></div><div className="sm:w-44"><Select label="Filter applications" value={appFilter} onChange={setAppFilter} options={['all','pending','shortlisted','accepted','declined']}/></div></div>}>{filteredApps.length?<div className="grid gap-4 xl:grid-cols-2">{filteredApps.map((a)=><article key={a._id} className="rounded-xl border border-slate-200 p-4 sm:p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-bold">{a.fullName}</h3><p className="mt-1 text-sm text-slate-500">{a.room?.title} · {a.college}</p></div><Badge value={a.status}/></div><div className="mt-4 grid gap-2 text-sm text-slate-600 sm:grid-cols-2"><p>Email <a className="font-medium text-indigo-700" href={`mailto:${a.email}`}>{a.email}</a></p><p>Phone <a className="font-medium text-indigo-700" href={`tel:${a.phone}`}>{a.phone}</a></p><p>Semester <b className="font-medium text-slate-800">{a.semester}</b></p><p>Move-in <b className="font-medium text-slate-800">{date(a.moveInDate)}</b></p></div>{a.message&&<p className="mt-3 rounded-lg bg-slate-50 p-3 text-sm leading-6 text-slate-600">{a.message}</p>}{a.student?.warnings?.map((w,i)=><p key={i} className="mt-2 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">Applicant note: {w.reason}</p>)}<div className="mt-4 flex flex-wrap gap-2 border-t border-slate-100 pt-4">{['pending','shortlisted'].includes(a.status)&&<><Button onClick={()=>updateApp(a._id,'shortlisted')}>Shortlist</Button><Button tone="success" onClick={()=>updateApp(a._id,'accepted')}>Accept</Button><Button tone="danger" onClick={()=>updateApp(a._id,'declined')}>Reject</Button></>}</div></article>)}</div>:<Empty title="No applications found" copy="Requests will show here as students apply for your rooms."/>}</Panel>}
    <Panel title="Account notices" subtitle="Keep an eye on owner account and listing review feedback.">{user.warnings?.length?<div className="space-y-2">{user.warnings.map((w,i)=><p key={i} className="rounded-lg bg-amber-50 p-3 text-sm text-amber-800">{w.reason} <span className="text-amber-700">· {date(w.createdAt)}</span></p>)}</div>:<p className="text-sm text-slate-500">No account notices.</p>}</Panel><ProfileSettings user={user} onUpdated={onUpdated}/>
  </div>;
}

function downloadCsv(filename, rows) {
  const escape=(value)=>`"${String(value??'').replaceAll('"','""')}"`;
  const csv=rows.map((row)=>row.map(escape).join(',')).join('\r\n');
  const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download=filename;link.click();URL.revokeObjectURL(link.href);
}

function AdminAccounts({ owners, students, query, setQuery, filter, setFilter, role, setRole, busy, moderateUser, createOwner, createdOwner, resetPassword, resetCredentials, createBusy, exportRows }) {
  const accounts=role==='owner'?owners:students;
  const shown=accounts.filter((account)=>(filter==='all'||account.accountStatus===filter)&&`${account.name} ${account.email} ${account.phone||''}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="space-y-5"><div className="flex gap-2 border-b border-slate-200"><button onClick={()=>{setRole('owner');setFilter('all');}} className={`border-b-2 px-4 py-3 text-sm font-semibold ${role==='owner'?'border-indigo-700 text-indigo-800':'border-transparent text-slate-500'}`}>Room owners <span className="ml-1 rounded-full bg-slate-100 px-2 py-0.5 text-xs">{owners.length}</span></button><button onClick={()=>{setRole('student');setFilter('all');}} className={`border-b-2 px-4 py-3 text-sm font-semibold ${role==='student'?'border-indigo-700 text-indigo-800':'border-transparent text-slate-500'}`}>Students <span className="ml-1 rounded-full bg-slate-100 px-2 py-0.5 text-xs">{students.length}</span></button></div>
    {role==='owner'&&<Panel title="Create an owner account" subtitle="Create an account for a host directly. A temporary password will be shown once for you to share securely."><form onSubmit={createOwner} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-[1fr_1fr_1fr_auto]"><input required name="name" placeholder="Owner full name" className="min-h-10 rounded-lg border border-slate-300 px-3 text-sm"/><input required name="email" type="email" placeholder="Owner email" className="min-h-10 rounded-lg border border-slate-300 px-3 text-sm"/><input name="phone" type="tel" placeholder="Phone (optional)" className="min-h-10 rounded-lg border border-slate-300 px-3 text-sm"/><Button disabled={createBusy}>{createBusy?'Creating…':'Create approved owner'}</Button></form>{createdOwner&&<div className="mt-4 rounded-lg border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-950"><p className="font-bold">Owner account created. Share these credentials with the owner:</p><p className="mt-2">Login email: <code className="font-semibold">{createdOwner.email}</code></p><p className="mt-1">Temporary password: <code className="font-semibold">{createdOwner.password}</code></p><p className="mt-2 text-xs text-emerald-800">The password is only shown here. Ask the owner to change it after signing in.</p><button type="button" onClick={()=>navigator.clipboard?.writeText(`Email: ${createdOwner.email}\nTemporary password: ${createdOwner.password}`)} className="mt-3 font-semibold underline">Copy credentials</button></div>}</Panel>}
    {resetCredentials&&<div className="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950"><p className="font-bold">Temporary password issued for {resetCredentials.email}</p><p className="mt-1">Share once with the account holder: <code className="font-bold">{resetCredentials.password}</code></p><button type="button" onClick={()=>navigator.clipboard?.writeText(resetCredentials.password)} className="mt-2 font-semibold underline">Copy temporary password</button></div>}
    <Panel title={role==='owner'?'Room owner accounts':'Student accounts'} subtitle={role==='owner'?'Approve hosts, review warnings and suspend accounts when necessary.':'Review student accounts, resolve reports and control access.'} action={<div className="flex w-full flex-col gap-2 sm:w-auto sm:flex-row"><div className="sm:w-60"><SearchField value={query} onChange={setQuery} placeholder="Search name, email or phone"/></div><div className="sm:w-44"><Select label="Filter account status" value={filter} onChange={setFilter} options={role==='owner'?['all','pending','approved','rejected','suspended']:['all','active','suspended','rejected']}/></div><Button tone="quiet" onClick={()=>exportRows(role==='owner'?'owners':'students')}>Export CSV</Button></div>}>{shown.length?<div className="grid gap-4 xl:grid-cols-2">{shown.map((account)=><article key={account._id} className="rounded-xl border border-slate-200 p-4 sm:p-5"><div className="flex flex-wrap justify-between gap-2"><div><h3 className="font-bold">{account.name}</h3><p className="mt-1 text-sm text-slate-500">{account.email} · {account.phone||'No phone provided'}</p></div><Badge value={account.accountStatus}/></div><p className="mt-3 text-xs text-slate-500">Joined {date(account.createdAt)} · {account.warningCount||0} warnings</p>{account.warnings?.map((warning,index)=><p key={index} className="mt-2 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">{warning.reason}</p>)}<div className="mt-4 flex flex-wrap gap-2 border-t border-slate-100 pt-4">{role==='owner'&&account.accountStatus!=='approved'&&<Button disabled={busy===account._id} tone="success" onClick={()=>moderateUser(account,{accountStatus:'approved'})}>Approve account</Button>}{role==='owner'&&account.accountStatus!=='rejected'&&<Button disabled={busy===account._id} tone="quiet" onClick={()=>moderateUser(account,{accountStatus:'rejected'})}>Reject</Button>}{role==='owner'&&account.accountStatus!=='suspended'&&<Button disabled={busy===account._id} tone="danger" onClick={()=>moderateUser(account,{accountStatus:'suspended'})}>Suspend</Button>}{role==='owner'&&account.accountStatus==='suspended'&&<Button disabled={busy===account._id} tone="success" onClick={()=>moderateUser(account,{accountStatus:'approved'})}>Restore account</Button>}{role==='student'&&account.accountStatus==='active'&&<Button disabled={busy===account._id} tone="danger" onClick={()=>moderateUser(account,{accountStatus:'suspended'})}>Suspend</Button>}{role==='student'&&account.accountStatus!=='active'&&<Button disabled={busy===account._id} tone="success" onClick={()=>moderateUser(account,{accountStatus:'active'})}>Reactivate</Button>}<Button disabled={busy===account._id} tone="quiet" onClick={()=>resetPassword(account)}>Issue temporary password</Button><Button disabled={busy===account._id} tone="quiet" onClick={()=>{const warning=window.prompt(`Reason to warn ${account.name}:`);if(warning?.trim())moderateUser(account,{warning});}}>Add warning</Button></div></article>)}</div>:<Empty title={`No ${role} accounts match`} copy="Try a different name, email, or status filter."/>}</Panel>
  </div>;
}

export function AdminDashboard({ user, onUpdated }) {
  const [overview,setOverview]=useState({}),[owners,setOwners]=useState([]),[students,setStudents]=useState([]),[rooms,setRooms]=useState([]),[apps,setApps]=useState([]),[error,setError]=useState(''),[tab,setTab]=useState('overview'),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[busy,setBusy]=useState(''),[accountRole,setAccountRole]=useState('owner'),[createdOwner,setCreatedOwner]=useState(null),[resetCredentials,setResetCredentials]=useState(null),[createBusy,setCreateBusy]=useState(false);
  const refresh=()=>Promise.all([api.get('/admin/overview'),api.get('/admin/users'),api.get('/admin/rooms'),api.get('/admin/applications')]).then(([o,u,r,a])=>{setOverview(o.data);setOwners(u.data.filter((x)=>x.role==='owner'));setStudents(u.data.filter((x)=>x.role==='student'));setRooms(r.data);setApps(a.data);setError('');}).catch((e)=>setError(getError(e)));
  useEffect(()=>{refresh();},[]);
  const moderateUser=async(account,payload)=>{setBusy(account._id);setError('');try{await api.patch(`/admin/users/${account._id}`,payload);await refresh();}catch(e){setError(getError(e));}finally{setBusy('');}};
  const createOwner=async(event)=>{event.preventDefault();setCreateBusy(true);setError('');setCreatedOwner(null);const form=Object.fromEntries(new FormData(event.currentTarget));try{const {data}=await api.post('/admin/owners',form);setCreatedOwner({email:data.owner.email,password:data.temporaryPassword});event.currentTarget.reset();await refresh();}catch(e){setError(getError(e));}finally{setCreateBusy(false);}};
  const resetPassword=async(account)=>{if(!window.confirm(`Issue a new temporary password for ${account.email}? The existing password will stop working.`))return;setBusy(account._id);setError('');setResetCredentials(null);try{const {data}=await api.post(`/admin/users/${account._id}/reset-password`);setResetCredentials({email:data.email,password:data.temporaryPassword});}catch(e){setError(getError(e));}finally{setBusy('');}};
  const moderateRoom=async(room,status)=>{const note=status==='available'?'':window.prompt(`Add a note for the owner about this ${status} decision:`,room.moderationNote||'');if(note===null)return;setBusy(room._id);setError('');try{await api.patch(`/admin/rooms/${room._id}`,{status,moderationNote:note});await refresh();}catch(e){setError(getError(e));}finally{setBusy('');}};
  const warnApplicant=async(application)=>{const reason=window.prompt(`Reason to flag ${application.fullName}'s application:`);if(!reason?.trim())return;setBusy(application._id);try{await api.post(`/admin/applications/${application._id}/warn`,{reason});await refresh();}catch(e){setError(getError(e));}finally{setBusy('');}};
  const moderateApplication=async(application,status)=>{setBusy(application._id);setError('');try{await api.patch(`/admin/applications/${application._id}/status`,{status});await refresh();}catch(e){setError(getError(e));}finally{setBusy('');}};
  const tabItems=[['overview','Overview'],['accounts','Accounts',owners.length+students.length],['rooms','Listings',rooms.length],['applications','Applications',apps.length]];
  const filtered=(list,getText,getStatus)=>list.filter((x)=>(filter==='all'||getStatus(x)===filter)&&getText(x).toLowerCase().includes(query.toLowerCase()));
  const shownRooms=filtered(rooms,(r)=>`${r.title} ${r.area} ${r.city} ${r.owner?.name||''} ${r.owner?.email||''}`,(r)=>r.status);
  const shownApps=filtered(apps,(a)=>`${a.fullName} ${a.email} ${a.college} ${a.room?.title||''}`,(a)=>a.status);
  const exportRows=(type)=>{const data=type==='rooms'?rooms.map((r)=>[r.title,r.owner?.name,r.owner?.email,r.area,r.city,r.rent,r.status]):type==='owners'||type==='students'?(type==='owners'?owners:students).map((a)=>[a.name,a.email,a.phone,a.role,a.accountStatus,a.warningCount]):apps.map((a)=>[a.fullName,a.email,a.phone,a.college,a.semester,a.room?.title,a.owner?.name,a.status,date(a.createdAt)]);downloadCsv(`rento-${type}.csv`,[[...(type==='rooms'?['Room','Owner','Owner email','Area','City','Rent','Status']:type==='owners'||type==='students'?['Name','Email','Phone','Role','Status','Warnings']:['Applicant','Email','Phone','College','Semester','Room','Owner','Status','Applied'])],...data]);};
  return <div className="space-y-6"><PageHeading eyebrow="Administration" title="Rento operations" copy="Review listings and accounts, monitor student requests, and keep the marketplace trustworthy." action={<Button tone="quiet" onClick={refresh}>Refresh data</Button>}/><ErrorNotice error={error}/>
    <DashboardTabs value={tab} onChange={(next)=>{setTab(next);setQuery('');setFilter('all');}} items={tabItems}/>
    {tab==='accounts'&&<AdminAccounts owners={owners} students={students} query={query} setQuery={setQuery} filter={filter} setFilter={setFilter} role={accountRole} setRole={setAccountRole} busy={busy} moderateUser={moderateUser} createOwner={createOwner} createdOwner={createdOwner} resetPassword={resetPassword} resetCredentials={resetCredentials} createBusy={createBusy} exportRows={exportRows}/>}
    {tab==='overview'&&<><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Stat label="Pending owners" value={overview.pendingOwners||0} detail="Account approvals" accent/><Stat label="Listings to review" value={overview.pendingRooms||0} detail={`${overview.availableRooms||0} currently published`}/><Stat label="New applications" value={overview.pendingApplications||0} detail={`${overview.applications||0} total requests`}/><Stat label="Students" value={overview.students||0} detail={`${overview.owners||0} room owners`}/></div><div className="grid gap-6 xl:grid-cols-3"><Panel title="Needs attention" subtitle="Priority queues across Rento."><div className="space-y-2">{[['Owner approvals',overview.pendingOwners,'accounts'],['Listing reviews',overview.pendingRooms,'rooms'],['New applications',overview.pendingApplications,'applications']].map(([label,count,dest])=><button key={dest} onClick={()=>{setTab(dest);setFilter('pending');setAccountRole('owner');}} className="flex w-full items-center justify-between rounded-lg border border-slate-200 px-4 py-3 text-left hover:bg-slate-50"><span className="text-sm font-medium text-slate-700">{label}</span><span className="rounded-full bg-amber-50 px-2.5 py-1 text-sm font-bold text-amber-800">{count||0}</span></button>)}</div></Panel><Panel title="Marketplace health" subtitle="Current inventory at a glance."><div className="space-y-4">{[['Available rooms',overview.availableRooms],['Booked rooms',overview.bookedRooms],['Total applications',overview.applications]].map(([label,value])=><div key={label} className="flex items-center justify-between border-b border-slate-100 pb-3 last:border-0 last:pb-0"><span className="text-sm text-slate-600">{label}</span><span className="font-bold">{value||0}</span></div>)}</div></Panel><Panel title="Quick links" subtitle="Open a review queue."><div className="grid gap-2">{[['Review listings','rooms'],['Manage owner and student accounts','accounts'],['Review applications','applications']].map(([label,dest])=><button key={dest} onClick={()=>setTab(dest)} className="rounded-lg bg-indigo-50 px-4 py-3 text-left text-sm font-semibold text-indigo-800 hover:bg-indigo-100">{label} →</button>)}</div></Panel></div></>}
    {tab==='rooms'&&<Panel title="Room listing moderation" subtitle="Inspect listing quality, billing information and owner records before publishing." action={<div className="flex w-full flex-col gap-2 sm:w-auto sm:flex-row"><div className="sm:w-64"><SearchField value={query} onChange={setQuery} placeholder="Search room or owner"/></div><div className="sm:w-44"><Select label="Filter listing status" value={filter} onChange={setFilter} options={['all','pending','available','booked','rejected','removed']}/></div><Button tone="quiet" onClick={()=>exportRows('rooms')}>Export CSV</Button></div>}>{shownRooms.length?<div className="grid gap-4 xl:grid-cols-2">{shownRooms.map((r)=><article key={r._id} className="overflow-hidden rounded-xl border border-slate-200"><div className="flex gap-4 p-4"><img src={r.images?.[0]||'https://images.unsplash.com/photo-1554995207-c18c203602cb?q=80&w=500'} alt="" className="h-24 w-28 shrink-0 rounded-lg object-cover sm:h-28 sm:w-36"/><div className="min-w-0 flex-1"><div className="flex flex-wrap justify-between gap-2"><h3 className="font-bold">{r.title}</h3><Badge value={r.status}/></div><p className="mt-1 text-sm text-slate-500">{r.area}, {r.city} · {r.size} m² · {r.roomType}</p><p className="mt-2 font-semibold">{money(r.rent)}<span className="font-normal text-slate-500"> / mo</span></p><p className="mt-1 text-xs text-slate-500">Owner {r.owner?.name} · {r.owner?.email}</p></div></div><div className="space-y-2 px-4 pb-4 text-sm text-slate-600"><p className="line-clamp-3">{r.description}</p><p>Water: {r.utilities?.water||'Not specified'} · Electricity: {r.utilities?.electricity||'Not specified'} · Deposit: {money(r.deposit)}</p>{r.moderationNote&&<p className="rounded-lg bg-amber-50 p-3 text-amber-800">Previous note: {r.moderationNote}</p>}</div><div className="flex flex-wrap gap-2 border-t border-slate-100 bg-slate-50 px-4 py-3">{r.status!=='available'&&<Button disabled={busy===r._id} tone="success" onClick={()=>moderateRoom(r,'available')}>Approve / publish</Button>}{r.status!=='rejected'&&<Button disabled={busy===r._id} tone="quiet" onClick={()=>moderateRoom(r,'rejected')}>Reject</Button>}{!['removed','rejected'].includes(r.status)&&<Button disabled={busy===r._id} tone="danger" onClick={()=>moderateRoom(r,'removed')}>Remove listing</Button>}{r.status==='available'&&<Button disabled={busy===r._id} tone="quiet" onClick={()=>moderateRoom(r,'booked')}>Mark booked</Button>}</div></article>)}</div>:<Empty title="No listings match" copy="Try another search or status filter."/>}</Panel>}
    {tab==='applications'&&<Panel title="Student applications" subtitle="Review requests, override owner decisions, and flag suspicious submissions." action={<div className="flex w-full flex-col gap-2 sm:w-auto sm:flex-row"><div className="sm:w-64"><SearchField value={query} onChange={setQuery} placeholder="Search applicant or room"/></div><div className="sm:w-44"><Select label="Filter application status" value={filter} onChange={setFilter} options={['all','pending','shortlisted','accepted','declined','withdrawn']}/></div><Button tone="quiet" onClick={()=>exportRows('applications')}>Export CSV</Button></div>}>{shownApps.length?<div className="grid gap-4 xl:grid-cols-2">{shownApps.map((a)=><article key={a._id} className="rounded-xl border border-slate-200 p-4 sm:p-5"><div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="font-bold">{a.fullName}</h3><p className="mt-1 text-sm text-slate-500">{a.college} · semester {a.semester}</p></div><Badge value={a.status}/></div><div className="mt-4 grid gap-1 text-sm text-slate-600"><p>Room <b className="font-semibold text-slate-800">{a.room?.title}</b> · {a.room?.area}, {a.room?.city}</p><p>Owner <b className="font-medium">{a.owner?.name}</b> · {a.owner?.email}</p><p>Contact <a href={`mailto:${a.email}`} className="text-indigo-700">{a.email}</a> · <a href={`tel:${a.phone}`} className="text-indigo-700">{a.phone}</a></p><p>Applied {date(a.createdAt)} · Move-in {date(a.moveInDate)}</p></div>{a.message&&<p className="mt-3 rounded-lg bg-slate-50 p-3 text-sm text-slate-600">{a.message}</p>}{a.warnings?.map((w,i)=><p key={i} className="mt-2 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">Warning: {w.reason}</p>)}<div className="mt-4 flex flex-wrap gap-2 border-t border-slate-100 pt-3"><Button disabled={busy===a._id} onClick={()=>moderateApplication(a,'shortlisted')}>Shortlist</Button><Button disabled={busy===a._id} tone="success" onClick={()=>moderateApplication(a,'accepted')}>Accept</Button><Button disabled={busy===a._id} tone="danger" onClick={()=>moderateApplication(a,'declined')}>Reject</Button><Button disabled={busy===a._id} tone="quiet" onClick={()=>warnApplicant(a)}>Add warning</Button></div></article>)}</div>:<Empty title="No applications match" copy="Try changing the search or status filter."/>}</Panel>}
    <ProfileSettings user={user} onUpdated={onUpdated}/>
  </div>;
}
